def count_primes(n):
    if n < 3:
        return 0
    is_prime = [True] * n                  # is_prime[i] stays True until a smaller prime is found to divide i
    is_prime[0] = is_prime[1] = False
    p = 2
    while p * p < n:                       # a composite number below n has a prime factor p with p * p < n
        if is_prime[p]:
            # smaller multiples of p already have a smaller prime factor and are crossed out, so start at p * p
            is_prime[p * p::p] = [False] * len(range(p * p, n, p))
        p += 1
    return sum(is_prime)
